pub(crate) fn proofs_here(t: &ProofsThread) -> (Option<String>, Option<i64>, Option<String>) {
    let mut line: Option<i64> = None;
    if t.at.file.is_some() && t.function.is_some() {
        let at = t.function_at.min(t.at.source.len() as i64);
        let mut before = 0;
        for b in t.at.breaks.iter() {
            let b = nikaia_std::num::value(b);
            if b < at { before += 1; }
        }
        line = (before + 1).into();
    }
    (match t.at.file.as_ref() {
        Some(__nikaia_it) => Some(nikaia_std::fs::path::text_of(&(__nikaia_it))),
        None => None,
    }, line, match t.function.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    })
}

pub fn proofs_shown(place: &(Option<String>, Option<i64>, Option<String>), root: &std::path::Path) -> String {
    let mut file: Option<String> = None;
    let path = match place.0.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    };
    if path.is_some() {
        let prefix = format!("{}/", nikaia_std::fs::path::text_of(&(root)));
        let shown: String = nikaia_std::index::or(match path.as_ref().unwrap().strip_prefix(&prefix) {
            Some(__nikaia_it) => Some(__nikaia_it.to_string()),
            None => None,
        }, || path.as_ref().unwrap().to_string().into());
        let line = place.1;
        if line.is_some() { file = Some(format!("{}:{}", shown, line.unwrap())); } else { file = Some(shown); }
    }
    let name = match place.2.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    };
    if file.is_some() && name.is_some() { return format!("{}, in `{}`", file.as_ref().unwrap(), name.as_ref().unwrap()); }
    if file.is_some() { return file.unwrap(); }
    if name.is_some() { return format!("in `{}`", name.as_ref().unwrap()); }
    String::from("a place the compiler did not name")
}

pub fn proofs_written(arena: &TermArena, facts: &[i64], goal: i64) -> String {
    let mut out: String = String::from("");
    for fact in facts.iter() {
        let fact = nikaia_std::num::value(fact);
        proofs_write_term(arena, fact, &mut out);
        out.push_str(";");
    }
    out.push_str("|");
    proofs_write_term(arena, goal, &mut out);
    out
}

pub(crate) fn proofs_write_term(arena: &TermArena, id: i64, out: &mut String) {
    if id < 0 || id >= arena.nodes.len() as i64 {
        out.push_str("?");
        return;
    }
    match nikaia_std::index::get(&arena.nodes, nikaia_std::index::at(id)) {
        SolverTerm::Bool(value) => { let value = *value; out.push_str(if value { "T" } else { "F" }); },
        SolverTerm::Int(value) => { let value = *value; out.push_str(&format!("i{},", value)); },
        SolverTerm::Var(name) => { out.push_str(&format!("v{}:{}", name.len() as i64, name)); },
        SolverTerm::Add(a, b) => { let a = *a; let b = *b; proofs_write_two("+", arena, a, b, out); },
        SolverTerm::Sub(a, b) => { let a = *a; let b = *b; proofs_write_two("-", arena, a, b, out); },
        SolverTerm::Mul(a, b) => { let a = *a; let b = *b; proofs_write_two("*", arena, a, b, out); },
        SolverTerm::Le(a, b) => { let a = *a; let b = *b; proofs_write_two("l", arena, a, b, out); },
        SolverTerm::Lt(a, b) => { let a = *a; let b = *b; proofs_write_two("<", arena, a, b, out); },
        SolverTerm::Ge(a, b) => { let a = *a; let b = *b; proofs_write_two("g", arena, a, b, out); },
        SolverTerm::Gt(a, b) => { let a = *a; let b = *b; proofs_write_two(">", arena, a, b, out); },
        SolverTerm::Eq(a, b) => { let a = *a; let b = *b; proofs_write_two("=", arena, a, b, out); },
        SolverTerm::Ne(a, b) => { let a = *a; let b = *b; proofs_write_two("!", arena, a, b, out); },
        SolverTerm::Neg(a) => {
            let a = *a;
            out.push_str("n");
            proofs_write_term(arena, a, out);
        },
        SolverTerm::Not(a) => {
            let a = *a;
            out.push_str("~");
            proofs_write_term(arena, a, out);
        },
        SolverTerm::Quot(a, k) => {
            let a = *a; let k = *k;
            out.push_str(&format!("q{},", k));
            proofs_write_term(arena, a, out);
        },
        SolverTerm::And(parts) => { proofs_write_all("&", arena, parts, out); },
        SolverTerm::Or(parts) => { proofs_write_all("|", arena, parts, out); },
        SolverTerm::Other => { out.push_str("o"); },
    }
}

pub(crate) fn proofs_write_two(tag: &str, arena: &TermArena, a: i64, b: i64, out: &mut String) {
    out.push_str(tag);
    proofs_write_term(arena, a, out);
    proofs_write_term(arena, b, out);
}

pub(crate) fn proofs_write_all(tag: &str, arena: &TermArena, parts: &[i64], out: &mut String) {
    out.push_str(&format!("{}{},", tag, parts.len() as i64));
    for part in parts.iter() {
        let part = nikaia_std::num::value(part);
        proofs_write_term(arena, part, out);
    }
}

pub(crate) fn proofs_known(t: &mut ProofsThread, written: &str) -> Option<ProofsAsked> {
    let held = match match t.known.get(written) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return None };
    let book = match t.book.as_mut() { Some(__nikaia_value) => __nikaia_value, None => return None };
    let entry = match book.entries.get(&held.key) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if *entry != held.entry { return None; }
    book.asked.insert(held.key.to_string());
    Some(held.asked.clone())
}

pub fn proofs_ask(t: &mut ProofsThread, arena: &TermArena, facts: &[i64], goal: i64) -> ProofsAsked {
    if t.book.is_none() { return proofs_search(&lg_normal_of(arena, facts, goal)).asked; }
    let written = proofs_written(arena, facts, goal);
    let known = proofs_known(t, &written);
    if known.is_some() { return known.unwrap(); }
    let normal = lg_normal_of(arena, facts, goal);
    let key = hash::sha256_hex(&normal.text().bytes().collect::<Vec<_>>());
    let mut recorded: Option<ProofsEntry> = None;
    {
        let book = match t.book.as_mut() { Some(__nikaia_value) => __nikaia_value, None => return ProofsAsked::Unknown };
        book.asked.insert(key.to_string());
        recorded = match book.entries.get(&key) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        };
    }
    if recorded.is_some() {
        let asked = proofs_read(&normal, recorded.as_ref().unwrap());
        if asked.is_some() {
            t.known.insert(written.to_string(), ProofsKnown { key: key.to_string(), entry: recorded.as_ref().unwrap().clone(), asked: asked.as_ref().unwrap().clone() });
            return asked.unwrap();
        }
    }
    let found = proofs_search(&normal);
    let entry = match found.entry.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    };
    if entry.is_some() { t.known.insert(written.to_string(), ProofsKnown { key: key.to_string(), entry: entry.as_ref().unwrap().clone(), asked: found.asked.clone() }); }
    let place = proofs_here(&t);
    let book = match t.book.as_mut() { Some(__nikaia_value) => __nikaia_value, None => return found.asked };
    book.searched += 1;
    book.searched_at.insert(place);
    if entry.is_some() { book.entries.insert(key, entry.unwrap()); } else { book.entries.remove(&key); }
    found.asked
}

pub(crate) fn proofs_read(normal: &LgNormal, entry: &ProofsEntry) -> Option<ProofsAsked> {
    match entry {
        ProofsEntry::Proved(text) => {
            let certificate = match lg_certificate_of(text) { Some(__nikaia_value) => __nikaia_value, None => return None };
            if lg_verify(&normal.arena, &normal.facts, normal.goal, &certificate).is_some() { return None; }
            return Some(ProofsAsked::Proved);
        },
        ProofsEntry::Refuted(text) => {
            let model = match lg_model_of(text) { Some(__nikaia_value) => __nikaia_value, None => return None };
            if !lg_verify_model(&normal.arena, &normal.facts, normal.goal, &model) { return None; }
            return Some(ProofsAsked::Refuted(normal.named(&model)));
        },
        ProofsEntry::Unknown(solver) => {
            if solver != PROOFS_SOLVER { return None; }
            return Some(ProofsAsked::Unknown);
        },
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProofsSearch {
    pub asked: ProofsAsked,
    pub entry: Option<ProofsEntry>,
}

pub(crate) fn proofs_search(normal: &LgNormal) -> ProofsSearch {
    match lg_check(&normal.arena, &normal.facts, normal.goal, &lg_budget()) {
        LgAnswer::Proved { ref certificate } => {
            let why = lg_verify(&normal.arena, &normal.facts, normal.goal, certificate);
            if why.is_some() { return ProofsSearch { asked: ProofsAsked::Rejected(format!("the solver's proof did not check ({}), which is a fault of the compiler", why.as_ref().unwrap().debug())), entry: None }; }
            return ProofsSearch { asked: ProofsAsked::Proved, entry: Some(ProofsEntry::Proved(lg_certificate_text(certificate))) };
        },
        LgAnswer::Refuted { ref model } => {
            if !lg_verify_model(&normal.arena, &normal.facts, normal.goal, model) { return ProofsSearch { asked: ProofsAsked::Unknown, entry: None }; }
            return ProofsSearch { asked: ProofsAsked::Refuted(normal.named(model)), entry: Some(ProofsEntry::Refuted(lg_model_text(model))) };
        },
        LgAnswer::Unknown { .. } => { return ProofsSearch { asked: ProofsAsked::Unknown, entry: Some(ProofsEntry::Unknown(PROOFS_SOLVER.to_string())) }; },
    }
}

pub fn proofs_invariants_here(t: &ProofsThread) -> collections::BTreeMap<i64, String> {
    let mut out: collections::BTreeMap<i64, String> = collections::BTreeMap::new();
    let path = match t.at.file.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return out };
    let book = match t.book.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return out };
    let file = format!("{}:", proofs_file_of(book, path));
    for (place, parts) in book.invariants.iter() {
        let rest = match place.strip_prefix(&file) { Some(__nikaia_value) => __nikaia_value, None => continue };
        let at = match proofs_byte_of(rest, &t.at.source) { Some(__nikaia_value) => __nikaia_value, None => continue };
        out.insert(at, parts.to_string());
    }
    out
}

pub fn proofs_record_at(t: &mut ProofsThread, used: &collections::BTreeMap<i64, String>, kind: &str) {
    let path = match match t.at.file.as_ref() {
        Some(__nikaia_it) => Some(nikaia_std::fs::path::clone(&(__nikaia_it))),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return };
    let source = t.at.source.to_string();
    let book = match t.book.as_mut() { Some(__nikaia_value) => __nikaia_value, None => return };
    let root = match book.root.as_ref() {
        Some(__nikaia_it) => Some(nikaia_std::fs::path::clone(&(__nikaia_it))),
        None => None,
    };
    if root.is_some() && !nikaia_std::fs::path::starts_with(&(path), root.as_ref().unwrap()) { return; }
    let file = proofs_file_of(book, &path);
    for (at, parts) in used.iter() {
        let place = format!("{}:{}{}", file, proofs_place_of(*at, &source), kind);
        book.invariants.insert(place.to_string(), parts.to_string());
        book.used.insert(place);
    }
}

pub fn proofs_asked_so_far(t: &ProofsThread) -> ProofsSoFar {
    let book = match t.book.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return ProofsSoFar { asked: collections::BTreeSet::new(), used: collections::BTreeSet::new() } };
    ProofsSoFar { asked: book.asked.to_owned(), used: book.used.to_owned() }
}

pub fn proofs_ask_again_from(t: &mut ProofsThread, before: &ProofsSoFar) {
    let book = match t.book.as_mut() { Some(__nikaia_value) => __nikaia_value, None => return };
    book.asked = before.asked.to_owned();
    book.used = before.used.to_owned();
}

pub fn proofs_place_of(at: i64, source: &str) -> String {
    let limit = at.min(source.len() as i64);
    let mut line = 1;
    let mut start: i64 = 0;
    let mut i: i64 = 0;
    for b in source.bytes() {
        if i >= limit { break; }
        if b == 10 {
            line += 1;
            start = i + 1;
        }
        i += 1;
    }
    format!("{}:{}", line, limit - start + 1)
}

pub fn proofs_byte_of(place: &str, source: &str) -> Option<i64> {
    let parts: Vec<&str> = place.split(':').collect::<Vec<_>>();
    if parts.len() != 2 { return None; }
    let line = match text::parse_i64(*nikaia_std::index::get(&parts, 0)) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let column = match text::parse_i64(*nikaia_std::index::get(&parts, 1)) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if line < 0 || column < 1 { return None; }
    let mut row: i64 = 1;
    let mut start: i64 = 0;
    let mut end = source.len() as i64;
    let mut i: i64 = 0;
    for b in source.bytes() {
        if b == 10 {
            if row >= line {
                end = i;
                break;
            }
            row += 1;
            start = i + 1;
        }
        i += 1;
    }
    if row < line { return None; }
    let found = start + column - 1;
    if found > end { return None; }
    Some(found)
}

pub(crate) fn proofs_file_of(book: &ProofsBook, path: &std::path::Path) -> String {
    let root = match book.root.as_ref() {
        Some(__nikaia_it) => Some(nikaia_std::fs::path::clone(&(__nikaia_it))),
        None => None,
    };
    if root.is_some() { return nikaia_std::fs::path::text_of(&(nikaia_std::index::or(nikaia_std::fs::path::strip_prefix(&(path), root.as_ref().unwrap()), || nikaia_std::fs::path::clone(&(path)).into()))); }
    nikaia_std::fs::path::text_of(&(path))
}

pub(crate) async fn proofs_long_files(dir: &std::path::Path) -> collections::BTreeMap<String, String> {
    let mut out: collections::BTreeMap<String, String> = collections::BTreeMap::new();
    let names = match fs::read_dir(dir, &fs::Root::Anywhere) {
        Ok(value) => value,
        Err(_error) => { return out; },
    };
    for name in names.iter() {
        let text = match fs::read_to_string(&nikaia_std::fs::path::join(&(dir), name), &fs::Root::Anywhere).await {
            Ok(value) => value,
            Err(_error) => { continue; },
        };
        out.insert(nikaia_std::fs::path::text_of(&(name)), text);
    }
    out
}

pub async fn proofs_book_read(root: &std::path::Path) -> ProofsBook {
    let mut book = proofs_book_empty();
    book.root = Some(nikaia_std::fs::path::clone(&(root)));
    let text = match fs::read_to_string(&nikaia_std::fs::path::join(&(root), std::path::Path::new(&(PROOFS_FILE))), &fs::Root::Anywhere).await {
        Ok(value) => value,
        Err(_error) => { return book; },
    };
    let long = proofs_long_files(&nikaia_std::fs::path::join(&(root), std::path::Path::new(&(PROOFS_LONG_DIR)))).await;
    for line in pb_read(&text, &|key| {
        match long.get(key) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }
    }) {
        if line.kind == "invariant" {
            let pair = match line.body.split_once(" ") { Some(__nikaia_value) => __nikaia_value, None => continue };
            if hash::sha256_hex(&pair.0.bytes().collect::<Vec<_>>()) == line.key { book.invariants.insert(pair.0.to_string(), pair.1.to_string()); }
            continue;
        }
        if line.kind == "proved" { book.entries.insert(line.key.to_string(), ProofsEntry::Proved(line.body.to_string())); } else if line.kind == "refuted" { book.entries.insert(line.key.to_string(), ProofsEntry::Refuted(line.body.to_string())); } else { book.entries.insert(line.key.to_string(), ProofsEntry::Unknown(line.body.to_string())); }
    }
    book
}

pub fn proofs_book_render(book: &ProofsBook) -> PbRendered {
    let mut lines: Vec<PbLine> = vec![];
    for (key, entry) in book.entries.iter() {
        if !book.asked.contains(key) { continue; }
        let line = match entry {
            ProofsEntry::Proved(text) => PbLine { key: key.to_string(), kind: String::from("proved"), body: text.to_string() },
            ProofsEntry::Refuted(text) => PbLine { key: key.to_string(), kind: String::from("refuted"), body: text.to_string() },
            ProofsEntry::Unknown(solver) => PbLine { key: key.to_string(), kind: String::from("unknown"), body: solver.to_string() },
        };
        lines.push(line);
    }
    for (place, parts) in book.invariants.iter() { if book.used.contains(place) { lines.push(PbLine { key: hash::sha256_hex(&place.bytes().collect::<Vec<_>>()), kind: String::from("invariant"), body: format!("{} {}", place, parts) }); } }
    lines.sort_by_key(|line| { line.key.to_string() });
    pb_render(&lines, PROOFS_LONG)
}

pub fn proofs_book_write(book: &ProofsBook, root: &std::path::Path, whole: &impl Fn(&std::path::Path, &str) -> Option<String>) -> Option<String> {
    let rendered = proofs_book_render(book);
    let failed = whole(&nikaia_std::fs::path::join(&(root), std::path::Path::new(&(PROOFS_FILE))), &rendered.text);
    if failed.is_some() { return std::convert::identity(failed); }
    let dir = nikaia_std::fs::path::join(&(root), std::path::Path::new(&(PROOFS_LONG_DIR)));
    if !rendered.long.is_empty() {
        match fs::create_dir(&dir, &fs::Root::Anywhere, true) {
            Ok(_) => {},
            Err(error) => { return Some(format!("{}", error)); },
        };
    }
    for (key, certificate) in rendered.long.iter() {
        let failed = whole(&nikaia_std::fs::path::join(&(dir), std::path::Path::new(&(key))), certificate);
        if failed.is_some() { return std::convert::identity(failed); }
    }
    let names = match fs::read_dir(&dir, &fs::Root::Anywhere) {
        Ok(value) => value,
        Err(_error) => { return None; },
    };
    for name in names.iter() {
        let text = nikaia_std::fs::path::text_of(&(name));
        if !rendered.long.contains_key(&text) && !text.ends_with(".partial") {
            match fs::remove(&nikaia_std::fs::path::join(&(dir), name), &fs::Root::Anywhere, false) {
                Ok(_) => {},
                Err(_error) => { },
            };
        }
    }
    if rendered.long.is_empty() {
        match fs::remove(&dir, &fs::Root::Anywhere, false) {
            Ok(_) => {},
            Err(_error) => { },
        };
    }
    None
}

pub async fn proofs_book_as_recorded(book: &ProofsBook, root: &std::path::Path) -> bool {
    let rendered = proofs_book_render(book);
    let text = match fs::read_to_string(&nikaia_std::fs::path::join(&(root), std::path::Path::new(&(PROOFS_FILE))), &fs::Root::Anywhere).await {
        Ok(value) => value,
        Err(_error) => { return false; },
    };
    if text != rendered.text { return false; }
    let dir = nikaia_std::fs::path::join(&(root), std::path::Path::new(&(PROOFS_LONG_DIR)));
    let names = match fs::read_dir(&dir, &fs::Root::Anywhere) {
        Ok(value) => value,
        Err(_error) => { return rendered.long.is_empty(); },
    };
    if (names.len() as i64) != rendered.long.len() as i64 { return false; }
    for (key, certificate) in rendered.long.iter() {
        let held = match fs::read_to_string(&nikaia_std::fs::path::join(&(dir), std::path::Path::new(&(key))), &fs::Root::Anywhere).await {
            Ok(value) => value,
            Err(_error) => { return false; },
        };
        if AsRef::<str>::as_ref(&(held)) != AsRef::<str>::as_ref(&(certificate)) { return false; }
    }
    true
}

pub fn proofs_book_len(book: &ProofsBook) -> i64 {
    let mut count = book.used.len() as i64;
    for key in book.entries.keys() { if book.asked.contains(key) { count += 1; } }
    count
}

